from cosmo_wap.bk import WS_ as _ws
from cosmo_wap.lib.utils import composite as _composite
from cosmo_wap.lib.utils import fill_multipoles as _fill

############################################################### wide separation terms
# three tracers and any LOS, from their angle-dependent forms in bk/WS_.py (generated by mathwap): ylm (so FoG) and
# every lx/lxmy up to l4, by projecting the mu1^a mu2^b coefficients exactly (the other parity's are zero stand-ins)
WA1, WA2, WARR, RR1, RR2, WAGR, RRGR = (
    _fill(_ws, type(n, (), {"__doc__": f"{n}: multipoles of bk.WS_.{_ws._BLOCKS[n][2].__name__}"}), n)
    for n in ('WA1', 'WA2', 'WARR', 'RR1', 'RR2', 'WAGR', 'RRGR')
)


############################################################### composite terms
# built at the end of bk_mt/__init__, once GR1 and GR2 have their l4, m > 0 and ylm from bk/PP_.py - as bk.combined
_WS = [("WA1", 1), ("RR1", 1), ("WA2", 0), ("WARR", 0), ("RR2", 0)]
_COMPOSITES = {
    "WS": ("Pure wide separation terms, RR + WA", _WS),
    "WSGR": ("Full wide separation effects including relativistic mixing", _WS + [("WAGR", 0), ("RRGR", 0)]),
    "Full": ("WS + GR", _WS + [("WAGR", 0), ("RRGR", 0), ("GR1", 1), ("GR2", 0)]),
}


def _install_composites(namespace):
    for name, (doc, parts) in _COMPOSITES.items():
        cls = _composite(name, doc, [(namespace[p], parity) for p, parity in parts], bk=True, module=__name__)
        namespace[name] = globals()[name] = cls
